export const meta = {
  name: 'triage-findings',
  description: 'Triage review findings (craft agents + GitHub PR comments) into one ordered, validated fix plan — no edits; a driver for the craft Rust CLI\'s step-by-step triage (`craft triage start | submit | status`): the binary decides every step — the gatherers, collapsing repeats, the project memory\'s recall and its judges setting aside what an active decision, deferred question or project rule already answers, the validators against the code at a pinned ref, the plan — and this engine only runs the agents each step hands out and hands their answers back (not yet observed live).',
  whenToUse: 'For every batch of review findings, whatever its size — from the report file of any review engine or the inline comments of a PR — when you want them validated against the code, deduped, conflict-checked, and turned into an ordered fix plan. Args: report=<path to a report file of any review engine> and/or pr=<GitHub PR number> (at least one; the binary refuses a run with neither); base=<the ref the findings were generated against — the reviewed head — which validation pins to>; prBase=<`git merge-base origin/<trunk> <reviewed head>`, the commit the PR forks from> only when the reviewed head is a branch diverging from trunk, beside a base it differs from (a finding is deferred as not this PR\'s only when shown there, else it comes back needs-decision); priorLedger=<array of prior {stable_id, verdict, reason} for idempotent re-runs>; priorDecisions=<the project records the launcher already holds, which add to those the run recalls>; repo=<absolute path> (the checkout the findings are in; default the session\'s); craftBin=<absolute path of a local craft build>; craftRoot=<absolute path of a craft plugin root>; run=<absolute path of a run directory> alone resumes a run the usage limit stopped or that was interrupted (`craft triage submit --resume`), and files again the record of a finished run whose record did not land. An argument it does not take, or a repo= or path that is not absolute, is refused with nothing run, filing an INCOMPLETE run record. Returns a `## Triage` block naming the absolute path of the plan file the binary wrote — read that file (`plan.json`): `plan_markdown` (the writing-plans-format fix plan, led by what did not run), `ledger` (the triage ledger, one row per finding with its verdict and reason; rows the memory set aside carry `sifted: true`) and `issues` (findings not this PR\'s, each with title and body, to file) — then the plan\'s summary; a run stopped on the usage limit says so and how to resume it with run=. The binary files the run\'s record itself when the run ends; this engine files only the INCOMPLETE record of a run the binary never finished. Once a workflow run has ended (completed, failed or stopped — not while you may still resume it), fold its real cost into the records it filed: `sh "<craft plugin root>/integrations/shared/craft-cli.sh" runs enrich-cost --run-id <wf_…>` (the plugin root is two directories above a craft skill\'s base directory), with the run id the Workflow completion names. Best-effort: if it fails, say so in one line and go on.',
  phases: [
    { title: 'Start', detail: 'without craftBin, a service agent gets the released binary of this version (sh integrations/shared/craft-cli.sh --ensure --print-path, no Node needed); a service agent runs `craft triage start` and returns the first tasks', model: 'haiku' },
    { title: 'Agents', detail: 'the step\'s tasks — gatherers, the memory\'s recall and judges, validators, the plan — run in parallel on the model the binary named, each reading its prompt file and writing its answer file in the run directory' },
    { title: 'Submit', detail: 'a service agent runs `craft triage submit`, which reads the answer files and, when the run ends, files its record itself', model: 'haiku' },
    { title: 'Record', detail: 'only for a run the binary never finished or a refused argument: an INCOMPLETE record filed through integrations/shared/craft-log-run.mjs', model: 'haiku' },
  ],
}
